<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Componente relacionado — <?=htmlspecialchars($positive['donation_number'])?></title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font:11px Arial;color:#172033}.toolbar{position:fixed;right:12px;top:12px}.sheet{border:1.5px solid #7f1d35;border-radius:9px;padding:15px;min-height:267mm}.head{display:flex;gap:20px;align-items:center;border-bottom:3px solid #7f1d35;padding-bottom:10px}.head img{width:145px}.head div{flex:1;text-align:center}.head h1{font-size:17px;margin:0}.head p{font-weight:bold;color:#7f1d35}.grid{display:grid;grid-template-columns:1fr 1fr;margin-top:15px;border:1px solid #ccd3dc}.field{padding:9px;min-height:50px;border-right:1px solid #ccd3dc;border-bottom:1px solid #ccd3dc}.field:nth-child(even){border-right:0}.field small{display:block;color:#667085;font-weight:bold;text-transform:uppercase;margin-bottom:5px}.history{margin-top:18px}.history h2{font-size:14px}.history article{display:grid;grid-template-columns:.7fr 1fr .7fr 1fr;gap:8px;padding:9px;border:1px solid #d8dee7;margin-top:7px}.labels{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}.labels div{height:125px;border:1px dashed #8993a4;padding:9px}.sign{width:55%;margin-top:70px;border-top:1px solid;text-align:center;padding-top:5px}@media print{.toolbar{display:none}}</style></head><body><button class="toolbar" onclick="print()">Imprimir / PDF</button><main class="sheet"><header class="head"><img src="/assets/images/bloodhub-logo-horizontal.png" alt="BloodHub"><div><h1>FORMULÁRIO DE TRABALHO BACTERIOLÓGICO</h1><p>REAÇÃO TRANSFUSIONAL · COMPONENTE RELACIONADO</p></div></header><section class="grid"><?php foreach([['Doação',$positive['donation_number']],['Paciente',$positive['patient_name']],['Hemocomponente relacionado',trim(($record['component_code']??'').' '.$record['hemocomponent'])],['Componente principal',$positive['source_component']],['Código LCQH principal',$positive['lcqh_code']],['Origem',$positive['origin']],['Situação',$situations[$record['situation']]??$record['situation']],['Local de armazenamento',$record['storage_location']],['Teste bacteriológico',empty($record['perform_bacteriology'])?'Não':'Sim — individual']] as[$label,$value]):?><div class="field"><small><?=$label?></small><strong><?=htmlspecialchars((string)($value?:'—'))?></strong></div><?php endforeach;?></section><?php if($record['tests']):?><section class="history"><h2>Histórico preservado</h2><?php foreach($record['tests'] as$t):?><article><strong><?=$t['attempt_type']==='retest'?'Reteste':'Teste 1'?></strong><span><?=$t['tested_at']?date('d/m/Y H:i',strtotime($t['tested_at'])):'Aguardando'?></span><span><?=$t['result']?($t['result']==='positive'?'Positivo':'Negativo'):'—'?></span><span><?=htmlspecialchars((string)($t['identified_bacteria']?:'—'))?></span></article><?php endforeach;?></section><?php endif;?><section class="labels"><div>Espaço para etiqueta da amostra</div><div>Espaço para etiqueta do frasco / teste individual</div></section><div class="sign">Responsável / data e hora</div></main><script>window.addEventListener('load',()=>setTimeout(()=>print(),150))</script></body></html>
